import json, os, time, torch
from transformers import AutoTokenizer, AutoModelForCausalLM, BitsAndBytesConfig

MODEL_ID = "Qwen/Qwen2.5-72B-Instruct"
REVISION = "495f39366efef23836d0cfae4fbe635880d2be31"
INSTRUMENT = 'You are classifying one synthetic medical MCQ for a development falsification probe.\n\nFIRST identify the proposition that actually discriminates the best answer.\nThen classify its epistemic type.\n\nA proposition is FOUNDATIONAL when its discriminating content is primarily anatomy, embryology/development, histology, cell biology, physiology, biochemistry/metabolism, microbiology/organism biology, pharmacodynamics/pharmacokinetics/receptor mechanism, or pathology/disease mechanism/microscopic lesion. It remains foundational even if clinicians commonly know or use it. CLINICALLY FAMILIAR does not mean NON-FOUNDATIONAL.\n\nApply this order:\n1) What proposition actually discriminates the answer?\n2) Is that proposition foundational by epistemic type?\n   - If NO, it may remain available as ordinary clinical/procedural knowledge.\n   - If YES, remove that proposition for the Removal Test even if a clinician commonly knows it.\n3) After removing that minimal foundational proposition while retaining non-foundational ordinary clinical/therapeutic/guideline/epidemiologic/procedural knowledge, can the best answer still be defensibly discriminated?\n   - YES => essential_foundational_dependency=false; removal_test=CAN_STILL_DISCRIMINATE; foundational_prerequisite=null\n   - NO => essential_foundational_dependency=true; removal_test=CANNOT_DEFENSIBLY_DISCRIMINATE; foundational_prerequisite=the minimal indispensable foundational principle\n\nANTI-INFLATION: a mechanism is not essential merely because it explains why a clinically obvious treatment/diagnosis works. If ordinary clinical knowledge alone selects the answer, return false.\n\nReturn ONLY one JSON object with exactly these keys:\nbest_answer\nessential_foundational_dependency\nfoundational_prerequisite\nremoval_test\nbrief_justification\n\nbest_answer must be A/B/C/D.\nessential_foundational_dependency must be JSON boolean.\nfoundational_prerequisite must be null when false and a concise string when true.\nNo markdown fences. No extra keys.\n'
ITEMS = [{'probe_id': 'R2b-X01', 'stem': 'Una fractura de la diáfisis humeral lesiona una estructura que discurre por el surco radial del húmero. ¿Qué déficit es más esperable?', 'options': {'A': 'Debilidad de extensión de muñeca y dedos', 'B': 'Pérdida aislada de aducción del pulgar', 'C': 'Incapacidad aislada para flexionar la cadera', 'D': 'Pérdida del reflejo fotomotor'}}, {'probe_id': 'R2b-X02', 'stem': 'Un vasodilatador libera óxido nítrico en músculo liso vascular. ¿Qué cambio intracelular media principalmente la relajación producida?', 'options': {'A': 'Aumento de GMPc por activación de guanilato ciclasa soluble', 'B': 'Aumento de IP3 por receptor Gq', 'C': 'Inhibición directa de la Na+/K+-ATPasa', 'D': 'Disminución de AMPc por proteína Gi'}}, {'probe_id': 'R2b-X03', 'stem': 'Un paciente con angina estable utiliza nitroglicerina sublingual para aliviar episodios breves de dolor torácico. ¿Qué instrucción es apropiada?', 'options': {'A': 'Usarla al inicio del episodio según indicación prescrita', 'B': 'Tomarla solo una vez al mes aunque haya dolor', 'C': 'Sustituirla por antibióticos', 'D': 'Usarla exclusivamente para fiebre'}}, {'probe_id': 'R2b-X04', 'stem': 'Un adulto con enfermedad por reflujo gastroesofágico frecuente inicia un inhibidor de la bomba de protones. ¿Cuál es el objetivo terapéutico principal?', 'options': {'A': 'Reducir la secreción ácida gástrica', 'B': 'Aumentar deliberadamente el ácido gástrico', 'C': 'Inducir hemólisis', 'D': 'Estimular agregación plaquetaria'}}, {'probe_id': 'R2b-X05', 'stem': 'Una paciente tiene adenocarcinoma colorrectal localizado, confirmado por anatomía patológica y estadificación. ¿Qué modalidad forma parte habitual del tratamiento curativo de enfermedad resecable?', 'options': {'A': 'Resección quirúrgica oncológica', 'B': 'Solo antihistamínicos', 'C': 'Diálisis crónica', 'D': 'Antibióticos indefinidos como tratamiento tumoral'}}, {'probe_id': 'R2b-X06', 'stem': 'En una biopsia de colon se observan glándulas irregulares infiltrando el estroma con desmoplasia. ¿Qué interpretación es la más adecuada?', 'options': {'A': 'Adenocarcinoma invasor', 'B': 'Pólipo hiperplásico no invasor', 'C': 'Tejido muscular normal', 'D': 'Hemorragia organizada sin neoplasia'}}, {'probe_id': 'R2b-X07', 'stem': 'Un adulto con enfermedad por reflujo gastroesofágico frecuente inicia un inhibidor de la bomba de protones que bloquea irreversiblemente la H+/K+-ATPasa de la célula parietal. ¿Cuál es el objetivo terapéutico principal?', 'options': {'A': 'Reducir la secreción ácida gástrica', 'B': 'Aumentar deliberadamente el ácido gástrico', 'C': 'Inducir hemólisis', 'D': 'Estimular agregación plaquetaria'}}, {'probe_id': 'R2b-X08', 'stem': 'Un paciente con intoxicación por metanol confirmada recibe tratamiento específico. ¿Cuál medida forma parte del manejo para impedir la formación de metabolitos tóxicos?', 'options': {'A': 'Fomepizol', 'B': 'Vitamina K', 'C': 'Protamina', 'D': 'Naloxona'}}, {'probe_id': 'R2b-X09', 'stem': 'Un paciente con asma persistente usa un corticosteroide inhalado como tratamiento controlador. ¿Cuál es la instrucción general correcta?', 'options': {'A': 'Usarlo de forma regular según la prescripción de control', 'B': 'Reservarlo exclusivamente para una hemorragia aguda', 'C': 'Tomarlo solo como antibiótico', 'D': 'Usarlo únicamente para tratar hipoglucemia'}}, {'probe_id': 'R2b-X10', 'stem': 'Tras la infección primaria por virus varicela-zóster, ¿dónde permanece latente el virus antes de una reactivación como herpes zóster?', 'options': {'A': 'Ganglios sensitivos de raíz dorsal o craneales', 'B': 'Eritrocitos maduros', 'C': 'Luz intestinal sin contacto celular', 'D': 'Matriz extracelular del cartílago'}}, {'probe_id': 'R2b-X11', 'stem': 'Un paciente con fractura cerrada de la diáfisis humeral presenta dolor intenso pero mantiene perfusión distal. ¿Cuál es la conducta inicial apropiada mientras se completa la evaluación ortopédica?', 'options': {'A': 'Inmovilizar el miembro y proporcionar analgesia', 'B': 'Realizar toracotomía urgente', 'C': 'Iniciar diálisis', 'D': 'Administrar trombólisis sistémica'}}, {'probe_id': 'R2b-X12', 'stem': 'Un adulto con herpes zóster localizado y reciente consulta por dolor y vesículas en un dermatoma. ¿Qué antiviral oral se utiliza habitualmente cuando está indicado?', 'options': {'A': 'Aciclovir o un análogo apropiado', 'B': 'Penicilina benzatínica', 'C': 'Metronidazol como monoterapia antiviral', 'D': 'Isoniazida'}}, {'probe_id': 'R2b-X13', 'stem': 'Un paciente con asma persistente usa un corticosteroide inhalado, que modifica transcripción génica y reduce mediadores inflamatorios, como tratamiento controlador. ¿Cuál es la instrucción general correcta?', 'options': {'A': 'Usarlo de forma regular según la prescripción de control', 'B': 'Reservarlo exclusivamente para una hemorragia aguda', 'C': 'Tomarlo solo como antibiótico', 'D': 'Usarlo únicamente para tratar hipoglucemia'}}, {'probe_id': 'R2b-X14', 'stem': 'En la intoxicación por metanol, la toxicidad ocular y metabólica se relaciona principalmente con la formación de ácido fórmico. ¿Qué enzima cataliza el primer paso cuya inhibición por fomepizol evita esa secuencia?', 'options': {'A': 'Alcohol deshidrogenasa', 'B': 'Piruvato carboxilasa', 'C': 'Glucógeno fosforilasa', 'D': 'Lipoproteína lipasa'}}, {'probe_id': 'R2b-X15', 'stem': 'Un recién nacido con labio hendido aislado está estable y se encuentra en evaluación multidisciplinaria. ¿Cuál es una prioridad clínica inicial apropiada?', 'options': {'A': 'Evaluar alimentación y coordinar seguimiento especializado', 'B': 'Administrar trombólisis', 'C': 'Indicar diálisis inmediata', 'D': 'Suspender toda alimentación de forma permanente'}}, {'probe_id': 'R2b-X16', 'stem': 'El labio hendido unilateral clásico se produce por falla de fusión entre:', 'options': {'A': 'Prominencia maxilar y prominencia nasal medial', 'B': 'Arcos vertebrales posteriores', 'C': 'Tabique urorrectal y membrana cloacal', 'D': 'Conductos paramesonéfricos entre sí'}}]

bnb = BitsAndBytesConfig(load_in_4bit=True, bnb_4bit_quant_type="nf4", bnb_4bit_compute_dtype=torch.bfloat16, bnb_4bit_use_double_quant=True)
tok = AutoTokenizer.from_pretrained(MODEL_ID, revision=REVISION, token=os.environ.get("HF_TOKEN"))
model = AutoModelForCausalLM.from_pretrained(
    MODEL_ID, revision=REVISION, token=os.environ.get("HF_TOKEN"),
    quantization_config=bnb, device_map="auto", torch_dtype=torch.bfloat16
)
model.eval()

def render(item):
    opts = "\n".join([f"{k}. {v}" for k,v in item["options"].items()])
    return f"""ITEM:\n{item['stem']}\n\nOPTIONS:\n{opts}"""

def one(item):
    messages=[{"role":"system","content":INSTRUMENT},{"role":"user","content":render(item)}]
    inputs = tok.apply_chat_template(messages, add_generation_prompt=True, return_tensors="pt").to(model.device)
    with torch.no_grad():
        out=model.generate(inputs, max_new_tokens=320, do_sample=False)
    text=tok.decode(out[0][inputs.shape[-1]:], skip_special_tokens=True).strip()
    try:
        parsed=json.loads(text)
        valid=isinstance(parsed,dict)
    except Exception as e:
        parsed=None; valid=False
    rec={"probe_id":item["probe_id"],"raw_text":text,"parsed":parsed,"structurally_parseable":valid}
    print("R2B_REC "+json.dumps(rec,ensure_ascii=False), flush=True)

print("R2B_META "+json.dumps({"model_id":MODEL_ID,"revision":REVISION,"n":len(ITEMS),"cuda":torch.cuda.is_available(),"gpu":torch.cuda.get_device_name(0) if torch.cuda.is_available() else None}), flush=True)
for it in ITEMS:
    one(it)
print("R2B_DONE "+json.dumps({"n":len(ITEMS)}), flush=True)
